"""Self-contained AQ SVG report; reuse ARVIS Radar's stylesheet and safe JSON pattern."""
import json
from .radar_v2 import STYLE


def render(payload):
    data = json.dumps(payload,ensure_ascii=False).replace('&','\\u0026').replace('<','\\u003c').replace('>','\\u003e')
    return TEMPLATE.replace('__ARVIS_STYLE__',STYLE).replace('__AQ_DATA__',data)


TEMPLATE = r'''<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; base-uri 'none'; form-action 'none'">
<title>ARVIS · KRX 시장 폭 / ADR20</title><style>__ARVIS_STYLE__
:root{--ink:#26394d;--muted:#65778a;--line:#dce5ed;--accent:#245aa7;--orange:#98601c}
body{background:#f2f5f8}main{max-width:1280px;padding:28px 22px}header{margin-bottom:22px;align-items:flex-start}.eyebrow{font-size:11px;letter-spacing:2px;color:var(--muted);font-weight:700;margin-bottom:8px}h1{font-size:29px;letter-spacing:-1px}.subtitle{color:var(--muted);margin-top:7px}.badge{padding:6px 10px}.snapshot{text-align:right}.snapshot strong{display:block;font-size:18px;margin-bottom:6px}.kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.metric{cursor:pointer;text-align:left;color:var(--ink);font:inherit;padding:18px;background:white;border:1px solid var(--line);border-radius:12px}.metric[aria-pressed=true]{border-color:var(--accent);box-shadow:inset 0 3px var(--accent)}.metric .big{font-size:36px;margin:10px 0 6px;letter-spacing:-1px}.metric h2{font-size:13px;color:var(--muted)}.metric small{font-size:11px}.provisional{font-size:11px;color:var(--orange);background:#fff5e2;border-radius:4px;padding:2px 6px;display:inline-block}.chart-card{margin-top:16px;padding:20px}.chart-head{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px}.chart-head h2{font-size:18px;margin:0}.controls{display:flex;flex-wrap:wrap;gap:14px;align-items:center}.segmented{display:flex;border:1px solid var(--line);border-radius:7px;padding:3px;gap:3px}button{cursor:pointer}button:focus-visible,select:focus-visible,svg:focus-visible{outline:3px solid #e5aa37;outline-offset:3px}.segmented button{font:inherit;font-size:12px;border:0;background:transparent;border-radius:5px;padding:7px 12px;color:var(--muted)}.segmented button[aria-pressed=true]{background:#26394d;color:white}select{font:inherit;padding:8px;border:1px solid var(--line);border-radius:6px;background:white;color:var(--ink)}.legend{display:flex;gap:16px;flex-wrap:wrap;font-size:11px;color:var(--muted);margin:18px 0 2px}.swatch{display:inline-block;width:18px;border-top:3px solid var(--accent);vertical-align:middle;margin-right:5px}.swatch.ref{border-color:#b0772a;border-top-style:dashed}.swatch.band{height:9px;border:0;background:#eaf0f8}.chart-wrap{position:relative;width:100%;margin-top:8px}#chart{display:block;width:100%;height:360px;touch-action:pan-y}.chart-foot{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;color:var(--muted);font-size:11px}#tip{position:fixed;z-index:10;pointer-events:none;background:#26394d;color:white;border-radius:8px;padding:10px 13px;font-size:12px;white-space:pre-line;box-shadow:0 4px 20px #152c4126;max-width:280px}.selected{margin-top:18px;border-top:1px solid var(--line);padding-top:14px}.selected h3{font-size:13px;margin:0 0 10px}.stats{display:grid;grid-template-columns:repeat(6,1fr);gap:8px}.stats div{background:#f6f8fb;padding:10px;border-radius:6px}.stats span{display:block;color:var(--muted);font-size:11px}.stats b{display:block;font-size:18px;margin-top:3px}.up b{color:#b94243}.down b{color:#3269aa}.summary-line{font-size:12px;color:var(--muted);margin-top:10px}.policy{display:grid;grid-template-columns:1.3fr 1fr;gap:16px;margin-top:16px}.policy section{padding:18px}.policy p{font-size:12px;line-height:1.65;color:var(--muted)}.policy h2{font-size:14px}.notice{font-size:12px;line-height:1.6;margin-top:16px;padding:12px 15px}.tablebox{max-height:340px;overflow:auto;margin-top:12px}table{min-width:760px}th{position:sticky;top:0}td,th{text-align:right;font-size:12px;white-space:nowrap}td:first-child,th:first-child{text-align:left}.status-null{color:#98601c}.footer{margin-top:20px;color:var(--muted);font-size:11px}.empty-list{overflow-wrap:anywhere;font-size:12px;line-height:1.7}.toggle{font-size:12px;color:var(--muted)}
@media(max-width:650px){main{padding:18px 12px}header{gap:12px;flex-direction:column}h1{font-size:24px}.snapshot{text-align:left;display:flex;gap:10px;align-items:center}.snapshot strong{font-size:14px;margin:0}.kpis{gap:7px}.metric{padding:12px 9px}.metric .big{font-size:27px}.metric h2{font-size:12px}.metric small{font-size:10px}.chart-card{padding:14px 10px}.chart-head{align-items:flex-start}.controls{width:100%;justify-content:space-between;gap:8px}.stats{grid-template-columns:repeat(3,1fr)}.policy{grid-template-columns:1fr;gap:0}.policy section{margin-top:10px}.legend{gap:10px}.chart-foot{font-size:10px}#chart{height:320px}.metric .provisional{font-size:10px}}
</style></head><body><main>
<header><div><p class="eyebrow">STOCK1 / ARVIS · C12-AQ</p><h1>시장의 폭을 읽다 <span class="muted">ADR20</span></h1><p class="subtitle">KRX 보통주 기반 · 최근 20거래일의 상승 수와 하락 수</p></div><div class="snapshot"><strong id="asof"></strong><span class="badge">저장된 일별 데이터</span></div></header>
<div class="kpis" id="kpis"></div>
<section class="chart-card"><div class="chart-head"><h2 id="chart-title">시장 폭 추이</h2><div class="controls"><label><span class="sr-only">시장 선택</span><select id="market" aria-label="시장 선택"><option value="COMBINED">통합 KOSPI + KOSDAQ</option><option value="KOSPI">KOSPI</option><option value="KOSDAQ">KOSDAQ</option></select></label><div class="segmented" role="group" aria-label="조회 기간"><button data-months="3" aria-pressed="true">3개월</button><button data-months="6" aria-pressed="false">6개월</button><button data-months="12" aria-pressed="false">1년</button></div></div></div>
<div class="legend"><span><i class="swatch"></i>기본 ADR20 · 보통주</span><label class="toggle"><input type="checkbox" id="reference" checked><i class="swatch ref"></i>UNKNOWN 포함 참고</label><span><i class="swatch band"></i>70–130 참고 범위</span><span>● 잠정값 · 하단 주황 표식: 미산출</span></div>
<div class="chart-wrap"><svg id="chart" tabindex="0" role="img" aria-label="ADR20 시계열, 방향키로 날짜 선택"></svg></div><div class="chart-foot"><span id="range"></span><span>마우스 · 터치 · ← → 키로 날짜 확인</span></div>
<div class="selected" aria-live="polite"><h3 id="selected-date"></h3><div class="stats" id="stats"></div><p class="summary-line" id="window-info"></p><p class="summary-line" id="counts-info"></p></div></section>
<div class="notice"><b>참고 기준, 자동 매매 신호 아님.</b> 70·100·130은 경험적 참고선입니다. 70 이하를 자동 매수, 130 이상을 자동 매도로 해석하지 않습니다. 잠정 수치이며 HTS의 전체 시장 ADR과 모집단이 다릅니다.</div>
<div class="policy"><section><h2>집계 원칙</h2><p>기본은 공식 분류 보통주만 사용합니다. 우선주·리츠·ETF·ETN·스팩·UNKNOWN, 미거래·가격 미형성·신규상장 당일·원문 이슈를 제외합니다. 보합은 별도 표시하며 상승·하락 합계에는 넣지 않습니다. 거래량 0은 거래정지 확정이 아닙니다.</p><p>공식 전일 대비(CMPPREVDD_PRC)를 우선합니다. 기준가격 차이가 있어도 공식 변화값으로 방향을 집계하고 검증 상태를 보존합니다. UNKNOWN 참고 계열은 적격 미분류를 추가하되 명시적 스팩 이름 힌트는 제외합니다.</p></section><section><h2>완전성과 해석 범위</h2><p id="coverage"></p><p>ADR20 = 100 × 20일 상승 수 합계 ÷ 20일 하락 수 합계. 통합은 양 시장 건수의 합입니다. 첫 19거래일·분모 0·예상 거래일 누락은 NULL로 남기며 그래프 선을 연결하지 않습니다. 공식 달력 및 상품 범위 검토 전 수치는 잠정입니다.</p><p>생성 시점의 과거 정정자료를 포함할 수 있습니다. 당시 알 수 있었던 정보만 사용하는 성과 검증 자료는 아닙니다.</p></section></div>
<section><details><summary>날짜별 계산 근거 · 선택 시장과 기간</summary><div class="tablebox"><table><thead><tr><th>날짜</th><th>기본 ADR20</th><th>참고 ADR20</th><th>상승</th><th>하락</th><th>보합</th><th>집계/제외</th><th>UNKNOWN</th><th>상태</th></tr></thead><tbody id="rows"></tbody></table></div></details><details><summary>양 시장 빈 응답 날짜 · 휴장 확정 아님</summary><p class="empty-list" id="empty-dates"></p></details></section>
<p class="footer">한국거래소 통계정보 · KRX Open API 저장 자료 · 독립 오프라인 리포트 · API 추가 호출/주문/운영 대시보드 연결 없음</p>
</main><div id="tip" role="tooltip" hidden></div><script type="application/json" id="aq-data">__AQ_DATA__</script><script>
'use strict';
const data=JSON.parse(document.getElementById('aq-data').textContent), report=data.report;
const $=id=>document.getElementById(id), fmt=x=>x===null||x===undefined?'—':Number(x).toLocaleString('ko-KR',{maximumFractionDigits:2,minimumFractionDigits:2}), num=x=>x===null||x===undefined?'—':Number(x).toLocaleString('ko-KR');
const status=s=>({provisional:'잠정',insufficient_history:'20일 미충족',missing_session:'거래일 누락·보류',zero_declines:'하락 합계 0'}[s]||s);
let months=3,market='COMBINED',visible=[],reference=[],selection=0,geometry=null;
const labels={COMBINED:'통합',KOSPI:'KOSPI',KOSDAQ:'KOSDAQ'};
const dailyNum=(r,value)=>r.complete?num(value):'—';
function el(tag,text){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;}
function cutoff(end,n){const d=new Date(end+'T00:00:00Z'),day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()-n);const last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();d.setUTCDate(Math.min(day,last));return d.toISOString().slice(0,10);}
const end=report.latest.COMBINED.common.day;
$('asof').textContent=end+' 기준';
$('coverage').textContent=`양 시장 확인 ${report.complete_sessions}거래일 · ${num(report.records)}행. 빈 응답 ${report.empty_dates.length}일은 관측 가용성 기준으로 제외했으며 공식 휴장일로 확정하지 않았습니다. 누락 거래일 ${report.missing_dates.length}일. 공식 달력 확인 전 잠정 계열입니다.`;
$('empty-dates').textContent=report.empty_dates.join(' · ')||'없음';
for(const m of ['KOSPI','KOSDAQ','COMBINED']){const a=report.latest[m].common,b=report.latest[m].common_unknown_reference;const button=el('button');button.className='metric';button.dataset.market=m;button.setAttribute('aria-pressed',String(m===market));button.append(el('h2',labels[m]+' ADR20'));const value=el('div',fmt(a.value));value.className='big';button.append(value);const tag=el('span',status(a.status));tag.className='provisional';button.append(tag);const delta=a.value!==null&&b.value!==null?Number(b.value)-Number(a.value):null;button.append(el('small',`UNKNOWN 참고 ${fmt(b.value)} · 차이 ${delta===null?'—':(delta>=0?'+':'')+fmt(delta)}%p`));button.onclick=()=>{$('market').value=m;market=m;update();};$('kpis').append(button);}
function svg(tag,attrs={},text){const e=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;return e;}
function pathFor(rows,x,y){let d='',open=false;rows.forEach((r,i)=>{if(r.value===null){open=false;return;}d+=(open?'L':'M')+x(i).toFixed(2)+','+y(Number(r.value)).toFixed(2);open=true;});return d;}
function draw(){const chart=$('chart'),width=Math.max(280,chart.clientWidth),height=chart.clientHeight,pad={l:42,r:20,t:20,b:36};chart.replaceChildren();chart.setAttribute('viewBox',`0 0 ${width} ${height}`);const all=visible.map(r=>r.value).concat($('reference').checked?reference.map(r=>r.value):[]).filter(v=>v!==null).map(Number);const min=Math.min(50,...all),max=Math.max(150,...all),margin=(max-min)*.1,lo=Math.max(0,min-margin),hi=max+margin;const x=i=>pad.l+(width-pad.l-pad.r)*i/Math.max(1,visible.length-1),y=v=>pad.t+(hi-v)/(hi-lo)*(height-pad.t-pad.b);geometry={width,height,pad,x,y};chart.append(svg('rect',{x:pad.l,y:y(130),width:width-pad.l-pad.r,height:y(70)-y(130),fill:'#eaf0f8'}));for(const value of [70,100,130]){chart.append(svg('line',{x1:pad.l,x2:width-pad.r,y1:y(value),y2:y(value),stroke:value===100?'#8195ab':'#ccd8e5','stroke-dasharray':'4 5'}));chart.append(svg('text',{x:pad.l-8,y:y(value)+4,'text-anchor':'end',fill:'#65778a','font-size':11},String(value)));}for(const value of [Math.round(lo),Math.round(hi)])chart.append(svg('text',{x:pad.l-8,y:y(value)+4,'text-anchor':'end',fill:'#65778a','font-size':10},String(value)));
const mainPath=svg('path',{d:pathFor(visible,x,y),fill:'none',stroke:'#245aa7','stroke-width':2.3,'stroke-linejoin':'round','data-series':'common'});chart.append(mainPath);if($('reference').checked)chart.append(svg('path',{d:pathFor(reference,x,y),fill:'none',stroke:'#b0772a','stroke-width':1.4,'stroke-dasharray':'5 4','data-series':'reference'}));
visible.forEach((r,i)=>{if(r.value===null)chart.append(svg('line',{x1:x(i),x2:x(i),y1:height-pad.b+4,y2:height-pad.b+10,stroke:'#b0772a','stroke-width':2,'data-missing':r.day}));else chart.append(svg('circle',{cx:x(i),cy:y(Number(r.value)),r:1.8,fill:'#245aa7','data-day':r.day}));});
const ticks=width<500?3:5;for(let i=0;i<ticks;i++){const k=Math.round(i*Math.max(0,visible.length-1)/(ticks-1));if(visible[k])chart.append(svg('text',{x:x(k),y:height-8,'text-anchor':i===0?'start':i===ticks-1?'end':'middle',fill:'#65778a','font-size':10},visible[k].day.slice(2)));}
if(!all.length)chart.append(svg('text',{x:width/2,y:height/2,'text-anchor':'middle',fill:'#98601c','font-size':14},'선택 구간 ADR20 미산출 · 아래 상태 확인'));
chart.append(svg('line',{id:'crosshair',x1:0,x2:0,y1:pad.t,y2:height-pad.b,stroke:'#8395a8','stroke-dasharray':'3 3',visibility:'hidden'}));show(selection);}
function show(index,event){if(!visible.length)return;selection=Math.max(0,Math.min(index,visible.length-1));const r=visible[selection],ref=reference[selection];$('selected-date').textContent=`${r.day} · ${labels[market]} · ${status(r.status)}`;$('stats').replaceChildren();for(const[label,value,cls]of [['ADR20',fmt(r.value),''],['상승',dailyNum(r,r.up),'up'],['하락',dailyNum(r,r.down),'down'],['보합',dailyNum(r,r.flat),''],['집계 대상',dailyNum(r,r.eligible),''],['제외',dailyNum(r,r.excluded),'']]){const div=el('div');div.className=cls;div.append(el('span',label),el('b',value));$('stats').append(div);}
$('window-info').textContent=`이동 구간 ${r.window_start} → ${r.window_end} · ${r.window_sessions}/20거래일 · Σ상승 ${num(r.up_sum)} / Σ하락 ${num(r.down_sum)} · UNKNOWN 참고 ${fmt(ref?.value)}`;
$('counts-info').textContent=`전체 ${num(r.total)} · UNKNOWN ${num(r.unknown)} · 거래량 0 ${num(r.zero_volume)} · 기준가격 차이 ${num(r.official_change_mismatch)} (적격 공식변화 사용 ${num(r.mismatch_used)})`+(r.missing_dates.length?' · 누락 '+r.missing_dates.join(', '):'');
if(geometry){const line=$('crosshair');line.setAttribute('x1',geometry.x(selection));line.setAttribute('x2',geometry.x(selection));line.setAttribute('visibility','visible');}
if(event){const tip=$('tip');tip.textContent=`${r.day} · ${labels[market]}\nADR20 ${fmt(r.value)} · ${status(r.status)}\n상승 ${dailyNum(r,r.up)} / 하락 ${dailyNum(r,r.down)} / 보합 ${dailyNum(r,r.flat)}\n20일 Σ상승 ${num(r.up_sum)} / Σ하락 ${num(r.down_sum)}\nUNKNOWN 참고 ${fmt(ref?.value)}`;tip.hidden=false;tip.style.left=Math.max(8,Math.min(event.clientX+14,innerWidth-tip.offsetWidth-10))+'px';tip.style.top=Math.max(8,Math.min(event.clientY+14,innerHeight-tip.offsetHeight-10))+'px';}}
function update(){const start=cutoff(end,months);visible=data.series.filter(r=>r.market===market&&r.universe==='common'&&r.day>=start);reference=data.series.filter(r=>r.market===market&&r.universe==='common_unknown_reference'&&r.day>=start);selection=Math.max(0,visible.length-1);$('chart-title').textContent=labels[market]+' · ADR20 추이';$('range').textContent=visible.length?`${visible[0].day} — ${end} · ${visible.length}거래일 · 미산출 ${visible.filter(r=>r.value===null).length}일`:'표시할 날짜 없음';document.querySelectorAll('[data-market]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.market===market)));$('rows').replaceChildren();visible.slice().reverse().forEach(r=>{const ref=reference.find(x=>x.day===r.day),tr=el('tr');for(const value of [r.day,fmt(r.value),fmt(ref?.value),dailyNum(r,r.up),dailyNum(r,r.down),dailyNum(r,r.flat),`${dailyNum(r,r.eligible)} / ${dailyNum(r,r.excluded)}`,num(r.unknown),status(r.status)])tr.append(el('td',value));if(r.value===null)tr.className='status-null';$('rows').append(tr);});$('tip').hidden=true;draw();}
$('market').onchange=()=>{market=$('market').value;update();};document.querySelectorAll('[data-months]').forEach(b=>b.onclick=()=>{months=Number(b.dataset.months);document.querySelectorAll('[data-months]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));update();});$('reference').onchange=draw;
function locate(e){if(!geometry)return;const rect=$('chart').getBoundingClientRect(),i=Math.round((e.clientX-rect.left-geometry.pad.l)/(geometry.width-geometry.pad.l-geometry.pad.r)*Math.max(1,visible.length-1));show(i,e);}
$('chart').onpointermove=locate;$('chart').onpointerdown=locate;$('chart').onpointerleave=e=>{if(e.pointerType==='mouse')$('tip').hidden=true;};$('chart').onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();show(e.key==='Home'?0:e.key==='End'?visible.length-1:selection+(e.key==='ArrowLeft'?-1:1));$('tip').hidden=true;}};
new ResizeObserver(()=>draw()).observe($('chart'));update();
</script></body></html>'''
